package cn.zhuatech.churnai.controller; import cn.zhuatech.churnai.common.ApiResponse; import cn.zhuatech.churnai.dto.ChurnAiDto.*; import cn.zhuatech.churnai.service.ChurnAiService; import cn.zhuatech.churnai.service.AiRiskAssessmentService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('DOMAIN_USER','ADMIN')") public class WorkspaceController {private final ChurnAiService service;private final AiRiskAssessmentService risk;public WorkspaceController(ChurnAiService service,AiRiskAssessmentService risk){this.service=service;this.risk=risk;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("客户挽留反馈已提交",service.report(id,request));}@PostMapping("/ai-risk-assessment") public ApiResponse<AiRiskAssessmentService.Result> assess(@Valid @RequestBody AiRiskAssessmentService.Request request){return ApiResponse.ok("AI 风险评估完成",risk.assess(request));}}
